def _pow2(k):
    if k >= 0:
        return Fraction(1 << k, 1)
    return Fraction(1, 1 << (-k))


def _floor_log2(x):
    # x is a positive Fraction
    n = x.numerator
    d = x.denominator
    L = n.bit_length() - d.bit_length()
    # adjust
    while _pow2(L + 1) <= x:
        L += 1
    while _pow2(L) > x:
        L -= 1
    return L


def _round_int(u, mode):
    # u: Fraction (nonzero), round to integer per mode
    n = u.numerator
    d = u.denominator  # > 0
    fl = n // d
    rem = n - fl * d  # 0 <= rem < d
    if rem == 0:
        return fl
    if mode == 'RTZ':
        return fl if n >= 0 else fl + 1
    if mode == 'RUP':
        return fl + 1
    if mode == 'RDN':
        return fl
    twice = 2 * rem
    if twice < d:
        return fl
    if twice > d:
        return fl + 1
    # tie
    if mode == 'RNE':
        return fl if (fl % 2 == 0) else fl + 1
    else:  # RNA, ties away from zero
