    def __init__(self, ebits, fbits):
        self.ebits = ebits
        self.fbits = fbits
        self.bias = (1 << (ebits - 1)) - 1
        self.F = 1 << fbits
        self.Eall = (1 << ebits) - 1
        self.emin = 1 - self.bias
        self.emax = self.Eall - 1 - self.bias
        self.width = 1 + ebits + fbits
        self.fracmask = self.F - 1

