import json
import sys
from fractions import Fraction


def _pow2(k):
    if k >= 0:
        return Fraction(1 << k, 1)
    return Fraction(1, 1 << (-k))


def _floor_log2(x):
    n = x.numerator
    d = x.denominator
    L = n.bit_length() - d.bit_length()
    while _pow2(L + 1) <= x:
        L += 1
    while _pow2(L) > x:
        L -= 1
    return L


def _round_int(u, mode):
    n = u.numerator
    d = u.denominator
    fl = n // d
    rem = n - fl * d
    if rem == 0:
        return fl
    if mode == 'RTZ':
        return fl if n >= 0 else fl + 1
    if mode == 'RUP':
        return fl + 1
    if mode == 'RDN':
        return fl
    twice = 2 * rem
    if twice < d:
        return fl
    if twice > d:
        return fl + 1
    if mode == 'RNE':
        return fl if (fl % 2 == 0) else fl + 1
    else:  # RNA
        return fl + 1 if n > 0 else fl


class Fmt:
    def __init__(self, ebits, fbits):
        self.ebits = ebits
        self.fbits = fbits
        self.bias = (1 << (ebits - 1)) - 1
        self.F = 1 << fbits
        self.Eall = (1 << ebits) - 1
        self.emin = 1 - self.bias
        self.emax = self.Eall - 1 - self.bias
        self.width = 1 + ebits + fbits
        self.fracmask = self.F - 1

    def decode(self, h):
        v = int(h, 16) & ((1 << self.width) - 1)
        s = (v >> (self.ebits + self.fbits)) & 1
        e = (v >> self.fbits) & self.Eall
        f = v & self.fracmask
        return s, e, f

    def classify(self, s, e, f):
        if e == self.Eall:
            if f == 0:
                return ('inf', s)
            quiet = (f >> (self.fbits - 1)) & 1
            return ('nan', bool(quiet))
        if e == 0:
            if f == 0:
                return ('fin', Fraction(0), s)
            val = Fraction(f) * _pow2(1 - self.bias - self.fbits)
            return ('fin', -val if s else val, s)
        val = Fraction(self.F + f) * _pow2(e - self.bias - self.fbits)
        return ('fin', -val if s else val, s)

    def max_finite_bits(self, sign):
        return ((sign << (self.ebits + self.fbits))
                | ((self.Eall - 1) << self.fbits) | (self.F - 1))

    def inf_bits(self, sign):
        return (sign << (self.ebits + self.fbits)) | (self.Eall << self.fbits)

    def canon_nan_bits(self):
        return (self.Eall << self.fbits) | (1 << (self.fbits - 1))

    def round_finite_signed(self, total, mode):
        """total: nonzero signed Fraction. Returns dict bits/flags."""
        sign = 1 if total < 0 else 0
        x = -total if total < 0 else total
        L = _floor_log2(x)
        qexp = max(self.emin - self.fbits, L - self.fbits)
        q = _pow2(qexp)
        u = total / q
        k = _round_int(u, mode)
        ak = k if k >= 0 else -k
        y = ak * q
        thresh = _pow2(self.emax + 1)
        if y >= thresh:
            flags = ['overflow', 'inexact']
            to_inf = (mode in ('RNE', 'RNA')
                      or (mode == 'RUP' and sign == 0)
                      or (mode == 'RDN' and sign == 1))
            if to_inf:
                bits = self.inf_bits(sign)
            else:
                bits = self.max_finite_bits(sign)
            return {'bits': format(bits, 'x'), 'flags': flags}
        flags = []
        if y != x:
            flags.append('inexact')
            if y < _pow2(self.emin):
                flags.append('underflow')
        if y == 0:
            bits = sign << (self.ebits + self.fbits)
        else:
            shift = qexp - (self.emin - self.fbits)
            t = ak << shift
            if t < self.F:
                e = 0
                f = t
            else:
                p = t.bit_length() - 1
                e = p - self.fbits + 1
                sig = t >> (e - 1)
                f = sig - self.F
            bits = (sign << (self.ebits + self.fbits)) | (e << self.fbits) | f
        return {'bits': format(bits, 'x'), 'flags': flags}


def solve(req):
    ebits = req['ebits']
    fbits = req['fbits']
    mode = req['mode']
    pairs = req['pairs']
    fmt = Fmt(ebits, fbits)

    parsed = [fmt.decode(h) for pair in pairs for h in pair]

    invalid = False
    has_nan = False
    for (s, e, f) in parsed:
        if e == fmt.Eall and f != 0:
            has_nan = True
            quiet = (f >> (fbits - 1)) & 1
            if not quiet:
                invalid = True

    classes = [fmt.classify(s, e, f) for (s, e, f) in parsed]

    inf_signs = set()
    for i in range(0, len(classes), 2):
        ca = classes[i]
        cb = classes[i + 1]
        if ca[0] == 'nan' or cb[0] == 'nan':
            continue
        a_inf = ca[0] == 'inf'
        b_inf = cb[0] == 'inf'
        a_zero = ca[0] == 'fin' and ca[1] == 0
        b_zero = cb[0] == 'fin' and cb[1] == 0
        if (a_inf and b_zero) or (b_inf and a_zero):
            invalid = True
        elif a_inf or b_inf:
            if a_inf and b_inf:
                sgn = ca[1] ^ cb[1]
            elif a_inf:
                sgn = ca[1] ^ cb[2]
            else:
                sgn = ca[2] ^ cb[1]
            inf_signs.add(sgn)

    if len(inf_signs) >= 2:
        invalid = True

    if invalid or has_nan:
        return {'bits': format(fmt.canon_nan_bits(), 'x'),
                'flags': ['invalid'] if invalid else []}

    if inf_signs:
        sgn = next(iter(inf_signs))
        return {'bits': format(fmt.inf_bits(sgn), 'x'), 'flags': []}

    total = Fraction(0)
    prod_info = []
    for i in range(0, len(classes), 2):
        ca = classes[i]
        cb = classes[i + 1]
        val = ca[1] * cb[1]
        total += val
        prod_info.append((val == 0, ca[2] ^ cb[2]))

    if total == 0:
        if mode == 'RDN':
            neg = True
        elif prod_info and all(z and sg == 1 for (z, sg) in prod_info):
            neg = True
        else:
            neg = False
        bits = (1 << (ebits + fbits)) if neg else 0
        return {'bits': format(bits, 'x'), 'flags': []}

    return fmt.round_finite_signed(total, mode)


def main():
    out = sys.stdout
    for line in sys.stdin:
        line = line.strip()
        if not line:
            continue
        req = json.loads(line)
        out.write(json.dumps(solve(req)) + '\n')
    out.flush()


if __name__ == '__main__':
    main()
